import React from 'react';

interface SimulationControlsProps {
  currentPhase: 'intro' | 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape';
  onAdvancePhase: (phase: 'intro' | 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => void;
  onLearnMore: () => void;
  onReset: () => void;
}

const SimulationControls: React.FC<SimulationControlsProps> = ({
  currentPhase,
  onAdvancePhase,
  onLearnMore,
  onReset
}) => {
  const phases = [
    { id: 'norton', name: 'Norton', color: '#ff6b35' },
    { id: 'microsoft', name: 'Microsoft', color: '#0078d4' },
    { id: 'google', name: 'Google', color: '#4285f4' },
    { id: 'malwarebytes', name: 'Malwarebytes', color: '#00a651' },
    { id: 'generic', name: 'Legal Threats', color: '#ff0000' },
    { id: 'advanced', name: 'Tech Support', color: '#8b0000' },
    { id: 'extreme', name: 'Ransomware', color: '#8b0000' },
    { id: 'escape', name: 'Escape Guide', color: '#28a745' }
  ];

  const currentPhaseIndex = phases.findIndex(phase => phase.id === currentPhase);

  return (
    <div 
      className="simulation-controls"
      style={{
        position: 'fixed',
        top: '20px',
        right: '20px',
        background: 'rgba(255, 255, 255, 0.95)',
        border: '3px solid #007bff',
        borderRadius: '12px',
        padding: '1.5rem',
        zIndex: 30000,
        boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        backdropFilter: 'blur(10px)',
        minWidth: '300px',
        maxWidth: '400px'
      }}
    >
      <div style={{ 
        textAlign: 'center', 
        marginBottom: '1rem',
        borderBottom: '2px solid #007bff',
        paddingBottom: '0.5rem'
      }}>
        <h3 style={{ 
          margin: 0, 
          color: '#007bff', 
          fontSize: '1.2rem',
          fontWeight: 'bold'
        }}>
          🎮 Simulation Controls
        </h3>
        <div style={{ 
          fontSize: '0.9rem', 
          color: '#666',
          marginTop: '0.25rem'
        }}>
          Protected from browser hijacking
        </div>
      </div>

      <div style={{ marginBottom: '1rem' }}>
        <div style={{ 
          fontSize: '0.9rem', 
          fontWeight: 'bold', 
          marginBottom: '0.5rem',
          color: '#333'
        }}>
          Current Phase: {currentPhase === 'intro' ? 'Intro' : phases[currentPhaseIndex]?.name}
        </div>
        <div style={{ 
          display: 'flex', 
          gap: '0.25rem',
          flexWrap: 'wrap'
        }}>
          {phases.map((phase, index) => (
            <div
              key={phase.id}
              style={{
                width: '20px',
                height: '20px',
                borderRadius: '50%',
                backgroundColor: phase.id === currentPhase ? phase.color : '#e9ecef',
                border: phase.id === currentPhase ? '2px solid #333' : '1px solid #ccc',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '0.6rem',
                color: phase.id === currentPhase ? 'white' : '#666',
                fontWeight: 'bold'
              }}
              onClick={() => onAdvancePhase(phase.id as any)}
              title={`${phase.name} (${index + 1}/${phases.length})`}
            >
              {index + 1}
            </div>
          ))}
        </div>
      </div>

      <div style={{ 
        display: 'flex', 
        gap: '0.5rem',
        flexWrap: 'wrap'
      }}>
        <button
          onClick={() => {
            const nextIndex = (currentPhaseIndex + 1) % phases.length;
            onAdvancePhase(phases[nextIndex].id as any);
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1,
            minWidth: '80px'
          }}
        >
          Next →
        </button>
        
        <button
          onClick={() => {
            const prevIndex = currentPhaseIndex === 0 ? phases.length - 1 : currentPhaseIndex - 1;
            onAdvancePhase(phases[prevIndex].id as any);
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#6c757d',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1,
            minWidth: '80px'
          }}
        >
          ← Previous
        </button>
      </div>

      <div style={{ 
        display: 'flex', 
        gap: '0.5rem',
        marginTop: '0.5rem'
      }}>
        <button
          onClick={onLearnMore}
          style={{
            padding: '0.5rem 1rem',
            background: '#28a745',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1
          }}
        >
          📚 Learn More
        </button>
        
        <button
          onClick={onReset}
          style={{
            padding: '0.5rem 1rem',
            background: '#dc3545',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1
          }}
        >
          🔄 Reset
        </button>
      </div>

      <div style={{ 
        marginTop: '1rem',
        padding: '0.75rem',
        background: 'rgba(0, 123, 255, 0.1)',
        borderRadius: '6px',
        border: '1px solid rgba(0, 123, 255, 0.2)',
        fontSize: '0.8rem',
        color: '#0056b3'
      }}>
        <strong>💡 Tip:</strong> Click any scareware button to see educational popups about why you should never click them in real life!
      </div>
    </div>
  );
};

export default SimulationControls;
